<?php require __DIR__.'/_layout.php';x1_require_role('operator');$db=x1_db();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){try{x1_check_csrf();if(!$db)throw new RuntimeException('SQLite required');$act=(string)($_POST['act']??'save');if($act==='save'){$id=(string)($_POST['id']??'');if($id==='')$id=x1_id();$existing=x1_db_one('SELECT * FROM devices WHERE id=?',[$id]);$cred=$existing['credentials_enc']??null;$user=(string)($_POST['provider_user']??'');$pass=(string)($_POST['provider_pass']??'');$url=(string)($_POST['provider_url']??'');if($user!==''||$pass!==''||$url!=='')$cred=x1_encrypt_secret(json_encode(['url'=>$url,'username'=>$user,'password'=>$pass],JSON_UNESCAPED_SLASHES));$now=date('c');x1_db_exec('INSERT INTO devices(id,device_id,mac,label,status,group_name,tags_json,premium_status,plan_id,expires_at,last_seen_at,last_ip,app_version,model,platform,notes,credentials_enc,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET device_id=excluded.device_id,mac=excluded.mac,label=excluded.label,status=excluded.status,group_name=excluded.group_name,tags_json=excluded.tags_json,premium_status=excluded.premium_status,plan_id=excluded.plan_id,expires_at=excluded.expires_at,app_version=excluded.app_version,model=excluded.model,platform=excluded.platform,notes=excluded.notes,credentials_enc=excluded.credentials_enc,updated_at=excluded.updated_at',[$id,trim((string)$_POST['device_id']),strtoupper(trim((string)$_POST['mac'])),trim((string)$_POST['label']),(string)$_POST['status'],trim((string)$_POST['group_name']),json_encode(array_values(array_filter(array_map('trim',explode(',',(string)$_POST['tags']))))),trim((string)$_POST['premium_status']),trim((string)$_POST['plan_id']),trim((string)$_POST['expires_at'])?:null,$existing['last_seen_at']??null,$existing['last_ip']??null,trim((string)$_POST['app_version']),trim((string)$_POST['model']),trim((string)$_POST['platform']),trim((string)$_POST['notes']),$cred,$existing['created_at']??$now,$now]);x1_audit('device_save',$id);}elseif($act==='status'){$id=(string)$_POST['id'];$status=(string)$_POST['status'];if(!in_array($status,['active','blocked','suspended','expired'],true))throw new RuntimeException('Invalid status');x1_db_exec('UPDATE devices SET status=?,updated_at=? WHERE id=?',[$status,date('c'),$id]);x1_audit('device_status',$id.' '.$status);}header('Location:devices.php');exit;}catch(Throwable $e){$msg=$e->getMessage();}}$rows=$db?x1_db_all('SELECT * FROM devices ORDER BY updated_at DESC LIMIT 1000'):[];top(tr('Devices','Dispositivos'));?><section class="card hero"><div class=eyebrow>DEVICE CONTROL</div><h2><?=tr('One operational view per WAVEO device','Uma visão operacional por dispositivo WAVEO')?></h2><p class=muted><?=tr('Status, identity, premium state, application version, grouping and encrypted provider credentials.','Estado, identidade, premium, versão da aplicação, grupos e credenciais de provider cifradas.')?></p></section><?php if(!$db):?><section class="notice warn"><?=tr('Production Devices requires PDO SQLite.','Devices de produção requer PDO SQLite.')?></section><?php endif?><?php if($msg):?><section class="notice warn"><?=h($msg)?></section><?php endif?><section class=section><h2><?=tr('Add / update device','Adicionar / atualizar dispositivo')?></h2><form method=post><input type=hidden name=csrf value="<?=x1_csrf()?>"><input type=hidden name=act value=save><div class=formgrid><label>Device ID<input name=device_id></label><label>MAC<input name=mac placeholder="AA:BB:CC:DD:EE:FF"></label><label><?=tr('Label','Nome')?><input name=label required></label><label>Status<select name=status><option>active</option><option>blocked</option><option>suspended</option><option>expired</option></select></label><label><?=tr('Group','Grupo')?><input name=group_name></label><label>Tags<input name=tags placeholder="living-room,premium"></label><label>Premium<input name=premium_status></label><label>Plan ID<input name=plan_id></label><labe